const item = $input.first().json.body || $input.first().json;

// Calculate Lead Tier
let score = 50;
const budget = String(item.budget || item.packageSelected || '').toLowerCase();
if (budget.includes('5,000+') || budget.includes('2,50,000') || budget.includes('enterprise') || budget.includes('vip')) {
  score += 35;
} else if (budget.includes('1,500') || budget.includes('1,00,000') || budget.includes('scale')) {
  score += 20;
}

if (item.phone && String(item.phone).length >= 10) score += 15;
if (item.email && !item.email.includes('gmail.com') && !item.email.includes('yahoo.com')) score += 15;

const tier = score >= 80 ? '🔥 HOT VIP' : score >= 60 ? '⚡ WARM' : '❄️ COLD';

// Auto-assign Sales Rep Pod
const service = String(item.division || item.targetService || '').toLowerCase();
let assignedRep = 'Rep 1: Bug Sprints & Web';
let repPhone = '+917015844885'; // Mr. Ayaan (Sales Lead)

if (service.includes('event') || service.includes('experience')) {
  assignedRep = 'Rep 7: Bangalore Summits';
} else if (service.includes('growth') || service.includes('ad')) {
  assignedRep = 'Rep 6: B2B Growth Retainers';
} else if (service.includes('business') || service.includes('strategy')) {
  assignedRep = 'Rep 9: Business Diagnostics';
} else if (service.includes('tech') || service.includes('ai')) {
  assignedRep = 'Rep 2: AI WhatsApp Bots';
}

const alertMsg = `🚨 NEW INBOUND LEAD DETECTED!\n━━━━━━━━━━━━━━━━━━━━\n👤 Name: ${item.name || 'N/A'}\n📧 Email: ${item.email || 'N/A'}\n📞 Phone: ${item.phone || 'N/A'}\n🏢 Division: ${item.division || 'General'}\n💰 Budget: ${item.budget || 'Not specified'}\n🎯 Score: ${score}/100 (${tier})\n👥 Assigned To: ${assignedRep}\n━━━━━━━━━━━━━━━━━━━━\n⚡ ACTION REQUIRED: Call in <3 mins!`;

return {
  ...item,
  leadScore: score,
  leadTier: tier,
  assignedRep,
  salesLeadPhone: repPhone,
  alertMsg,
  timestamp: new Date().toISOString()
};
